/**
 * Legacy 301 redirects: old WooCommerce/WPML URLs -> new storefront URLs.
 *
 * The map is generated by
 *   backend/woo-medusa-migration/scripts/build-301-redirects.py
 * from the old sitemaps + the migration data. Regenerate and copy
 * `legacy-redirects.json` here whenever products/categories change.
 *
 * Keys are old paths WITHOUT a trailing slash (locale prefix included),
 * e.g. "/es/pijamas-navidenas/familiar" or "/christmas-pyjamas/family/elf-irish-check".
 * Values are new internal paths, e.g. "/es-es/pijamas-de-navidad/familia".
 */
import map from "@lib/data/legacy-redirects.json"

const LEGACY: Record<string, string> = map as Record<string, string>

/** WooCommerce archive pagination suffix, e.g. "/nl/kerst-pyjama/gezin-familie/page/2". */
const LEGACY_PAGINATION = /\/page\/(\d+)$/

function lookup(key: string): string | null {
  return LEGACY[key] ?? LEGACY[decodeURIComponent(key)] ?? null
}

/**
 * Returns the new path for an old URL, or null if there is no legacy redirect.
 * Paginated archive URLs (`/<category>/page/N`) resolve via their category and
 * carry the page over as `?page=N`, which is what the storefront paginates on.
 */
export function resolveLegacyRedirect(pathname: string): string | null {
  const key = pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname
  const direct = lookup(key)
  if (direct) {
    return direct
  }

  const pagination = key.match(LEGACY_PAGINATION)
  if (!pagination) {
    return null
  }

  const target = lookup(key.slice(0, pagination.index))
  if (!target) {
    return null
  }

  const page = Number(pagination[1])
  return page > 1 ? `${target}?page=${page}` : target
}

/**
 * Legacy WordPress media library -> CDN.
 *
 * Old image URLs look like `/wp-content/uploads/2022/08/<file>.png`. The CDN
 * stores every image flat under `/images/`, keyed by file name only, e.g.
 * `https://cdn.thechristmasfabric.com/images/<file>.png`.
 */
const LEGACY_MEDIA_PREFIX = "/wp-content/uploads/"
const LEGACY_MEDIA_CDN = "https://cdn.thechristmasfabric.com/images"

/** Returns the absolute CDN URL for an old `/wp-content/uploads/...` path, or null if it isn't one. */
export function resolveLegacyMediaRedirect(pathname: string): string | null {
  if (!pathname.startsWith(LEGACY_MEDIA_PREFIX)) {
    return null
  }

  const file = pathname.slice(pathname.lastIndexOf("/") + 1)
  return file ? `${LEGACY_MEDIA_CDN}/${file}` : null
}
